import {loadGravity} from './gravity.mjs';
let magPromise;
async function magneticValues(){if(!magPromise)magPromise=(async()=>{const r=await fetch('global/magnetic-06m.bin',{signal:AbortSignal.timeout(120000)});if(!r.ok)throw Error('Não foi possível carregar a grade magnética global.');const b=await r.arrayBuffer();if(b.byteLength!==12960000)throw Error('Grade global incompleta.');const v=new DataView(b),a=new Int16Array(b.byteLength/2);for(let i=0;i<a.length;i++)a[i]=v.getInt16(i*2,true);return a;})().catch(e=>{magPromise=undefined;throw e;});return magPromise;}
export async function loadGlobal(mode){const [r,values]=await Promise.all([fetch(`global/${mode}-summary.json`),mode==='magnetic'?magneticValues():loadGravity()]);if(!r.ok)throw Error('Resumo global indisponível.');return {data:await r.json(),values};}
export function makeGlobalMagneticLayer(L,values){return new (L.GridLayer.extend({createTile(c){const tile=document.createElement('canvas');tile.width=tile.height=128;const ctx=tile.getContext('2d'),img=ctx.createImageData(128,128),n=2**c.z;const xx=Array.from({length:128},(_,x)=>Math.floor(((((c.x+(x+.5)/128)/n*360)%360)+360)%360*10));for(let y=0;y<128;y++){const lat=Math.atan(Math.sinh(Math.PI*(1-2*(c.y+(y+.5)/128)/n)))*180/Math.PI,iy=Math.floor((lat+90)*10);for(let x=0;x<128;x++){const raw=values[iy*3600+xx[x]];if(raw===-32768||raw===undefined)continue;const v=raw*.4,t=Math.min(Math.abs(v)/500,1),end=v<0?[44,91,181]:[197,67,30];img.data.set([247+(end[0]-247)*t,247+(end[1]-247)*t,243+(end[2]-243)*t,190],(y*128+x)*4);}}ctx.putImageData(img,0,0);return tile;}}))({tileSize:256,opacity:.8,maxZoom:15,attribution:'NOAA EMAG2 v3 · GMT · grade de 6′'});}
